        }
      }
    },
    "fidelity": {
      "const": "sketch",
      "description": "Marks the artifact as a non-binding sketch so nobody mistakes it for a spec"
    },
    "reasoning": {
      "type": "string",
      "description": "Private scratchpad; not forwarded downstream."
    }
  },
  "allOf": [
    {
      "if": { "properties": { "status": { "const": "decided" } }, "required": ["status"] },
      "then": { "required": ["decisions"], "properties": { "decisions": { "minItems": 1 } } }
    }
  ]
}

